/// 按输入前缀查询英文候选（命中 ≤limit 条，按 freq_rank 升序；未命中返回空）。
/// 输入任意大小写，内部小写化后匹配查键。
#[must_use]
pub fn en_words_with_prefix(prefix: &str, limit: usize) -> Vec<(&'static str, u16)> {
    if prefix.is_empty() || limit == 0 {
        return Vec::new();
    }
    let p = prefix.to_ascii_lowercase();
    let start = EN_WORDS.partition_point(|e| prefix_lt(e.norm, &p));
    let mut hits: Vec<(&'static str, u16)> = Vec::new();
    for e in &EN_WORDS[start..] {
        if !e.norm.starts_with(&p) {
            break;
        }
        hits.push((e.word, e.freq_rank));
    }
    hits.sort_by_key(|(_, rank)| *rank);
    hits.truncate(limit);
    hits
}

/// 字节序前缀严格小于比较（`a < b` 且 `a` 不是 `b` 的前缀）。
fn prefix_lt(a: &str, b: &str) -> bool {
    match a.as_bytes().cmp(b.as_bytes()) {
        std::cmp::Ordering::Less => true,
        std::cmp::Ordering::Greater => false,
        std::cmp::Ordering::Equal => false,
    }
}

#[cfg(test)]
mod tests {
    use super::{en_words_with_prefix, EN_WORDS};

    #[test]
    fn 表有序且无重复查键() {
        for pair in EN_WORDS.windows(2) {
            assert!(
                pair[0].norm < pair[1].norm,
                "表未按 norm 升序: {} vs {}",
                pair[0].norm,
                pair[1].norm
            );
        }
        let mut seen = std::collections::HashSet::new();
        for e in EN_WORDS {
            assert!(seen.insert(e.norm), "重复查键: {}", e.norm);
            assert!(!e.norm.is_empty() && !e.word.is_empty());
        }
    }

    #[test]
    fn 词表规模达标() {
        assert!(
            EN_WORDS.len() >= 10000,
            "D-12 应 ≥10000 词，实际 {}",
            EN_WORDS.len()
        );
    }

    #[test]
    fn 验收命中() {
        assert_eq!(
            en_words_with_prefix("python", 8).first().map(|(w, _)| *w),
            Some("python")
        );
        assert_eq!(
            en_words_with_prefix("pytho", 8).first().map(|(w, _)| *w),
            Some("python")
        );
        assert_eq!(
            en_words_with_prefix("iphone", 8).first().map(|(w, _)| *w),
            Some("iPhone")
        );
        assert_eq!(
            en_words_with_prefix("iphon", 8).first().map(|(w, _)| *w),
            Some("iPhone")
        );
        assert_eq!(
            en_words_with_prefix("api", 8).first().map(|(w, _)| *w),
            Some("API")
        );
        // 大小写输入同命中（D-09）
        assert_eq!(
            en_words_with_prefix("PYTHO", 8).first().map(|(w, _)| *w),
            Some("python")
        );
        assert_eq!(
            en_words_with_prefix("PYTHON", 8).first().map(|(w, _)| *w),
            Some("python")
        );
        // 前缀补充
        assert!(!en_words_with_prefix("py", 8).is_empty());
    }

    #[test]
    fn 不命中返回空() {
        assert!(en_words_with_prefix("", 8).is_empty());
        assert!(en_words_with_prefix("xyzabc123", 8).is_empty());
        assert!(en_words_with_prefix("zzzz9", 8).is_empty());
    }

    #[test]
    fn 候选数量受限于上限() {
        let hits = en_words_with_prefix("a", 3);
        assert!(hits.len() <= 3);
    }
}
